files.content:
* {
  box-sizing: border-box;
}

body {
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

.header {


  max-width: 1200px;
  margin: 0 auto;
  padding: 25px 15px;
  background-color: #ffc802;
  display: flex;
}

.logo__image {
  width: 150px;
}

.menu__list {
  list-style: none;
}

.menu__list-item {
  margin-left: 10px;
}

.menu__list-link {
  color: #000;
  font-weight: 600;
  text-decoration: none;
  text-transform: uppercase;
}

.menu__list-link:hover {
  text-decoration: underline;
}
